  const context={base:props.base,branch:props.branch,principal:principal.value,generation,latest:props.latestCommit};
  const confirmed=await app.confirmAction('仅当两个版本之间只有项目标签或纯列宽变化时，才会更新当前样本草稿的基础版本。你的样本编辑会保留并保存为本机草稿，不会产生提交；若正文、样本模板或其他文件改变，服务会拒绝同步。是否继续？',{title:'同步元数据版本',confirmLabel:'核对并同步草稿基点'});
