    const state=await post<DatasetDraftState>(props.base+'/dataset/draft/rebase',payload);
    if(context.base!==props.base||context.branch!==props.branch||context.principal!==principal.value||context.generation!==generation)return;
    serverDraft.value=state.draft;serverDraftSummary.value=state.draft??state.summary;serverDraftIssue.value=state.issue;
    if(state.issue)throw new Error(state.issue.message);
    pending.value=state.draft?structuredClone(state.draft.operations):[];pinned.value=state.draft?.baseCommit??payload.expectedCommit;showDiff.value=false;draftDiff.value=undefined;
